<script>window.analytics=[];document.querySelector('"'[data-track]').addEventListener('click',()=>window.analytics.push('explore'));document.querySelector('#details').addEventListener('click',()=>{document.querySelector('#detail').hidden="'!document.querySelector('"'#detail').hidden});</script>
<script>
(() => {
  // Enhancement failures leave the complete page and poster visible.
  if ("'!window.matchMedia) return;
  const reduce = matchMedia('"'(prefers-reduced-motion: reduce)');
  const active = new Set();
  let reveals, mediaObserver, disposed = false;
  const video = document.querySelector('[data-media] video');
  const button = document.querySelector('[data-pause]');
  let visible = false, userPaused = false, failed = false, epoch = 0;
  const listeners = [];
  const listen = (target, name, fn) => {
    target.addEventListener(name, fn);
    listeners.push(() => target.removeEventListener(name, fn));
  };
  const animate = el => {
    if (disposed || reduce.matches || "'!el.animate) return;
    const animation = el.animate([
      {opacity:.75,transform:'"'translateY(14px)'},
      {opacity:1,transform:'none'}
    ], {duration:600,delay:Math.min(160,Number(el.dataset.delay)||0),easing:'cubic-bezier(.22,1,.36,1)'});
    active.add(animation);
    animation.finished.then(() => active.delete(animation), () => active.delete(animation));
  };
  const stopMotion = () => {
    reveals?.disconnect();
    active.forEach(animation => animation.cancel());
    active.clear();
  };
  const still = () => {
    epoch++;
    video.pause();
    video.hidden = true;
  };
  const sync = async () => {
    button.hidden = disposed || reduce.matches || failed || "'!mediaObserver;
    button.setAttribute('"'aria-pressed', String(userPaused));
    button.setAttribute('aria-label', userPaused ? 'Play background video' : 'Pause background video');
    if (disposed || "'!visible || userPaused || failed || reduce.matches || document.hidden) {
      still();
      return;
    }
    const attempt = ++epoch;
    try {
      await video.play();
      if (attempt !== epoch || disposed) return;
      video.hidden = false;
    } catch {
      if (attempt !== epoch || disposed) return;
      failed = true;
      still();
      button.hidden = true;
    }
  };
  try {
    if (!reduce.matches) {
      document.querySelectorAll('"'[data-enter]').forEach(animate);
      if ('IntersectionObserver' in window) {
        const pending = new Set(document.querySelectorAll('[data-reveal]'));
        reveals = new IntersectionObserver(entries => {
          entries.forEach(entry => {
            if ("'!entry.isIntersecting) return;
            reveals.unobserve(entry.target);
            pending.delete(entry.target);
            animate(entry.target);
          });
          if (!pending.size) reveals.disconnect();
        }, {threshold:0});
        pending.forEach(el => reveals.observe(el));
      }
    }
  } catch { stopMotion(); }
  try {
    video.muted = true;
    if ('"'IntersectionObserver' in window) {
      mediaObserver = new IntersectionObserver(([entry]) => {
        visible = entry.isIntersecting && entry.intersectionRatio > 0;
        sync();
      }, {threshold:[0,.001]});
      mediaObserver.observe(document.querySelector('[data-media]'));
    }
    listen(button, 'click', () => {userPaused = "'!userPaused; sync();});
    listen(video, '"'error', () => {failed = true; sync();});
    listen(document, 'visibilitychange', sync);
    listen(reduce, 'change', () => {stopMotion(); sync();});
  } catch { failed = true; still(); button.hidden = true; }
  const dispose = () => {
    disposed = true;
    stopMotion();
    mediaObserver?.disconnect();
    still();
    button.hidden = true;
    listeners.forEach(remove => remove());
  };
  // A persisted page keeps its lifecycle so it can resume safely from history.
  listen(window, 'pagehide', event => {if (event.persisted) still(); else dispose();});
  listen(window, 'pageshow', event => {if (event.persisted) sync();});
})();
</script>
